namespace Fm27Editor.Core.Players;

public enum RoleGroup { Goalkeeper, Defence, Midfield, Wing, Attack }

public sealed record RoleDefinition(
    string Code,
    string Name,
    RoleGroup Group,
    PlayerAttribute[] Primary,
    PlayerAttribute[] Secondary);

public sealed record RoleScore(RoleDefinition Role, double Score);

