    public static double Evaluate(RoleDefinition role, PlayerRecord player)
    {
        ArgumentNullException.ThrowIfNull(role);
        ArgumentNullException.ThrowIfNull(player);
        double primarySum = 0;
        foreach (var attr in role.Primary) primarySum += player.Attribute(attr);
        double secondarySum = 0;
        foreach (var attr in role.Secondary) secondarySum += player.Attribute(attr);
        return (primarySum / role.Primary.Length) * 3.0 + (secondarySum / role.Secondary.Length) * 2.0;
    }

    public static IReadOnlyList<RoleScore> ForPlayer(PlayerRecord player)
    {
        ArgumentNullException.ThrowIfNull(player);
        var scores = new RoleScore[All.Count];
        for (int i = 0; i < All.Count; i++)
            scores[i] = new RoleScore(All[i], Evaluate(All[i], player));
        Array.Sort(scores, static (a, b) => b.Score.CompareTo(a.Score));
        return scores;
    }

    public static RoleScore BestRole(PlayerRecord player, RoleGroup? group = null)
    {
        ArgumentNullException.ThrowIfNull(player);
        RoleScore? best = null;
        foreach (var role in All)
        {
            if (group is { } g && role.Group != g) continue;
            double score = Evaluate(role, player);
            if (best is null || score > best.Score)
                best = new RoleScore(role, score);
        }
        return best!;
    }

    public static RoleScore BestFitRole(PlayerRecord player)
    {
        ArgumentNullException.ThrowIfNull(player);
        bool gkOnly = player.Position(PlayerPosition.Goalkeeper) >= 15;
        return gkOnly ? BestRole(player, RoleGroup.Goalkeeper) : BestRole(player);
    }

    /// <summary>Progress rate on a 0.5-10.0 scale: average(Determination, Ambition, Professionalism) / 2.</summary>
    public static double ProgressRate(PlayerRecord player)
    {
        ArgumentNullException.ThrowIfNull(player);
        int sum = player.Attribute(PlayerAttribute.Determination)
            + player.PersonalityValue(PersonalityAttribute.Ambition)
            + player.PersonalityValue(PersonalityAttribute.Professionalism);
        return (sum / 3.0) / 2.0;
    }

    /// <summary>Core mental percentage (5-100): average(Bravery, Composure, Concentration, Determination, Teamwork) * 5.</summary>
    public static double CoreMentalPercent(PlayerRecord player)
    {
        ArgumentNullException.ThrowIfNull(player);
        int sum = player.Attribute(PlayerAttribute.Bravery)
            + player.Attribute(PlayerAttribute.Composure)
            + player.Attribute(PlayerAttribute.Concentration)
            + player.Attribute(PlayerAttribute.Determination)
            + player.Attribute(PlayerAttribute.Teamwork);
        return sum;
    }
